package glitch

import data.glitch_lib

# Define weak cryptographic indicators (algorithms, modes, protocols)
weak_crypto_patterns := {
    "DES", "3DES", "RC4", "MD5", "SHA1", "RSA-1024", "ECB",
    "TLSv1.0", "TLSv1.1", "SSLv3", "md5_crypt", "SunX509"
}

# Check if a string value contains weak cryptographic indicators
check_weak_crypto_string(str_val) {
    is_weak := weak_crypto_patterns[_]
    regex.match(sprintf("(?i).*%s.*", [is_weak]), str_val)
}

# Check for insecure encryption configurations like encryption_enabled = false
check_insecure_config(attr) {
    attr.name == "encryption_enabled"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Check for hardcoded keys or insecure key management
check_hardcoded_keys(attr) {
    attr.name == "secret_key"
    attr.value.ir_type == "String"
    count(attr.value.value) > 0
}

# Helper to check value for weak crypto (recursive for complex types)
check_value_weak_crypto(value) {
    value.ir_type == "String"
    check_weak_crypto_string(value.value)
} else {
    value.ir_type == "Hash"
    some kv
    value.value[kv]
    check_value_weak_crypto(kv.value)
} else {
    value.ir_type == "Array"
    some item
    value.value[item]
    check_value_weak_crypto(item)
}

# Main rule for AtomicUnit attributes (Ansible, Puppet, etc.)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
